 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # The grid is divided into rectangular cells by full-width/full-height
    # separator lines. Identify those uniform lines, then examine each cell.
    uniform_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    uniform_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}
    sep_counts = Counter(grid[r][0] for r in uniform_rows)
    sep_counts.update(grid[0][c] for c in uniform_cols)
    separator = sep_counts.most_common(1)[0][0]
    row_cuts = {r for r in uniform_rows if grid[r][0] == separator}
    col_cuts = {c for c in uniform_cols if grid[0][c] == separator}

    def intervals(length, cuts):
        result, start = [], 0
        for i in range(length):
            if i in cuts:
                if start < i:
                    result.append(range(start, i))
                start = i + 1
        if start < length:
            result.append(range(start, length))
        return result

    row_blocks = intervals(h, row_cuts)
    col_blocks = intervals(w, col_cuts)
    nonseparator = [grid[r][c] for r in range(h) for c in range(w)
                    if r not in row_cuts and c not in col_cuts]
    background = Counter(nonseparator).most_common(1)[0][0]
    marker_colors = [color for color, count in Counter(nonseparator).items()
                     if color != background]
    marker = marker_colors[0]

    output = []
    for rows in row_blocks:
        out_row = []
        for cols in col_blocks:
            hit = False
            for r in rows:
                for c in cols:
                    if grid[r][c] != marker:
                        continue
                    if (r + 1 in rows and grid[r + 1][c] == marker) or \
                       (c + 1 in cols and grid[r][c + 1] == marker):
                        hit = True
            out_row.append(1 if hit else background)
        output.append(out_row)
    return output


if __name__ == '__main__':
    pass
